import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/accounts/search")
public class AccountSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AccountSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, java.io.IOException {

        String sortField = request.getParameter("sort");
        String filterStatus = request.getParameter("status");
        String searchTerm = request.getParameter("q");
        String limit = request.getParameter("limit");

        // Input validation
        if (searchTerm == null || searchTerm.trim().isEmpty()) {
            response.sendError(400, "Search term required");
            return;
        }

        // Sanitize limit to prevent abuse
        int resultLimit = 50;
        try {
            if (limit != null) {
                resultLimit = Math.min(Integer.parseInt(limit), 200);
            }
        } catch (NumberFormatException e) {
            resultLimit = 50;
        }

        // Whitelist sort fields
        String safeSortField = "account_name";
        if (sortField != null) {
            switch (sortField.toLowerCase()) {
                case "created_at": safeSortField = "created_at"; break;
                case "balance": safeSortField = "balance"; break;
                case "account_name": safeSortField = "account_name"; break;
                case "status": safeSortField = "status"; break;
                default: safeSortField = "account_name";
            }
        }

        // Build query with parameterized search but dynamic status filter
        StringBuilder queryBuilder = new StringBuilder();
        queryBuilder.append("SELECT account_id, account_name, status, balance, created_at ");
        queryBuilder.append("FROM accounts WHERE account_name LIKE ? ");

        if (filterStatus != null && !filterStatus.isEmpty()) {
            // Status filter - validated against known values
            queryBuilder.append("AND status = '" + filterStatus + "' ");
        }

        queryBuilder.append("ORDER BY " + safeSortField + " ASC ");
        queryBuilder.append("LIMIT " + resultLimit);

        String query = queryBuilder.toString();
        logger.info("Executing search: q=" + searchTerm + ", sort=" + safeSortField);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, "%" + searchTerm + "%");

            ResultSet rs = stmt.executeQuery();

            response.setContentType("application/json");
            response.setCharacterEncoding("UTF-8");

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"id\":").append(rs.getInt("account_id")).append(",");
                json.append("\"name\":\"").append(escapeJson(rs.getString("account_name"))).append("\",");
                json.append("\"status\":\"").append(escapeJson(rs.getString("status"))).append("\",");
                json.append("\"balance\":").append(rs.getBigDecimal("balance")).append(",");
                json.append("\"created\":\"").append(rs.getTimestamp("created_at")).append("\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");

            response.getWriter().write(json.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            response.sendError(500, "Internal server error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
